import heapq


def _ledger(sequence_first, discounted, refund):
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            ident = event.get("id", "anonymous:" + str(pos))
            key = ((seq, event.get("revision", 0), pos) if sequence_first
                   else (event.get("revision", 0), pos))
            if ident not in chosen or key > chosen[ident][0]:
                chosen[ident] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(n, d=10000):
            return (n + d // 2) // d if mode == "half_up" else n // d

        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = net if discounted else raw
            tax = rounded(base * event.get("tax_bp", 0))
            amount = net + tax
            if refund and event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    versions = {name: sorted(packages[name], key=lambda row: row["version"])
                for name in names}
    choices = [[-1] + [row["version"] for row in versions[name]] for name in names]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    for vector in product(*choices):
        selected = {name: version for name, version in zip(names, vector) if version != -1}
        if any(name not in selected or selected[name] != version
               for name, version in pins.items()):
            continue
        if any(version in blocked.get(name, []) for name, version in selected.items()):
            continue
        ok = True
        for name, bounds in data["roots"].items():
            if name not in selected or not bounds[0] <= selected[name] <= bounds[1]:
                ok = False
                break
        if not ok:
            continue

        rows = {name: {row["version"]: row for row in versions[name]}
                for name in selected}
        closure = set()
        edges = {}
        pending = list(data["roots"])
        while pending and ok:
            name = pending.pop()
            if name in closure:
                continue
            closure.add(name)
            if name not in selected:
                ok = False
                break
            row = rows[name][selected[name]]
            active = [dep for dep in row.get("deps", [])
                      if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in active:
                other = dep["name"]
                if other not in selected or not dep["min"] <= selected[other] <= dep["max"]:
                    ok = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not ok or closure != set(selected):
            continue

        done, visiting = set(), set()
        def acyclic(name):
            if name in visiting:
                return False
            if name in done:
                return True
            visiting.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            visiting.remove(name)
            done.add(name)
            return True
        if not all(acyclic(name) for name in closure):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    options = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i - 1]["end"] > ordered[i]["start"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        chosen_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and chosen_ids < best_ids)):
            best_value, best_ids = value, chosen_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    best = {initial: data["start"]}
    heap = [(data["start"], source, initial_mask, data["coupons"])]
    while heap:
        time, node, mask, left = heapq.heappop(heap)
        state = (node, mask, left)
        if best.get(state) != time:
            continue
        if node == data["target"] and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], left)]
            if left:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                durations.append((duration, left - 1))
            next_mask = mask | bit.get(edge["v"], 0)
            for duration, next_left in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_left)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(heap, (arrival, edge["v"], next_mask, next_left))
    return {"arrival": None}


